package render

import "strings"

// stopSummary uses only invocation/result metadata, never live job inspection.
// Old persisted presentations are not regenerated by this renderer.
func stopSummary(args, result map[string]any) string {
	kind, _ := result["kind"].(string)
	label, _ := result["label"].(string)
	id, _ := args["job_id"].(string)
	if child, _ := args["child_id"].(string); strings.TrimSpace(Clean(child)) != "" {
		kind, id = "child", child
	}
	reference := JobReference(kind, label, id)
	if reference == "" {
		return "**job_stop**"
	}
	// JobReference clips before escaping so escapes can never be cut in half.
	return "**job_stop(" + EscapeInline(reference) + ")**"
}
